func canPartition(nums []int) bool {
    sum := 0
    for _, n := range nums {
        sum += n
    }
    if sum%2 != 0 {
        return false
    }
    target := sum / 2
    dp := make([]bool, target+1)
    dp[0] = true
    for _, n := range nums {
        // 倒序遍历，确保每个元素只用一次
        for j := target; j >= n; j-- {
            dp[j] = dp[j] || dp[j-n]
        }
    }
    return dp[target]
}
